def fibonacci(n):
    if n <= 0:
        return 0
    elif n == 1 or n == 2:
        return 1
    else:
        a, b = 1, 1
        for _ in range(3, n + 1):
            a, b = b, a + b
        return b

n = 30
result = fibonacci(n)
print(f"The {n}th Fibonacci number (F1=1, F2=1) is: {result}")

def is_prime(n):
    """Checks if a number n is prime."""
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def count_primes(limit):
    """Counts the number of prime numbers below the limit."""
    count = 0
    for number in range(1, limit):
        if is_prime(number):
            count += 1
    return count

# We want to count primes below 10,000 (i.e., up to 9999)
limit = 10000
prime_count = count_primes(limit)
print(f"There are {prime_count} prime numbers below {limit}.")
